script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let tmpSelectedArr = [];
    let selectedRows = event.payload.selectedRows;

    for (let key in selectedRows) {
        if (selectedRows.hasOwnProperty(key)) {
            tmpSelectedArr.push(key);
        }
    }

    return {
        propName: "selectedRowList",
        value: tmpSelectedArr
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let header = {
        label: api.item.value.question,
        variant: "secondary",
        size: "md",
    };

    return header;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.state.operationToPerform === "add") {
        return helpers.translateSync("Add new contributing indicator PO project");
    } else {
        return helpers.translateSync("Update contributing indicator PO project");
    }
    return '';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (["autoselect", "select"].includes(event.payload.item.actionSource)) {
        return {
            propName: "tmpCIRm2mPO",
            value: {
                "contributing_indicator_registry": event.payload.item.id,
                "po_project_id": api.state.tmpCIRm2mPO.po_project_id,
                "active": api.state.tmpCIRm2mPO.active
            }
        };
    } else {
        return {
            propName: "tmpCIRm2mPO",
            value: {
                "contributing_indicator_registry": "",
                "po_project_id": api.state.tmpCIRm2mPO.po_project_id,
                "active": api.state.tmpCIRm2mPO.active
            }
        };
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (["autoselect", "select"].includes(event.payload.item.actionSource)) {
        return {
            propName: "tmpCIRm2mPO",
            value: {
                "contributing_indicator_registry": api.state.tmpCIRm2mPO.contributing_indicator_registry,
                "po_project_id": event.payload.item.id,
                "active": api.state.tmpCIRm2mPO.active
            }
        };
    } else {
        return {
            propName: "tmpCIRm2mPO",
            value: {
                "contributing_indicator_registry": api.state.tmpCIRm2mPO.contributing_indicator_registry,
                "po_project_id": "",
                "active": api.state.tmpCIRm2mPO.active
            }
        };
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        propName: "tmpCIRm2mPO",
        value: {
            "contributing_indicator_registry": api.state.tmpCIRm2mPO.contributing_indicator_registry,
            "po_project_id": api.state.tmpCIRm2mPO.po_project_id,
            "active": event.payload.value
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let initialData = api.state.initialData;
    let currentData = api.state.tmpCIRm2mPO;

    if (
        initialData.active == currentData.active &&
        initialData.po_project_id == currentData.po_project_id
    ) {
        return true;
    } else {
        if (!currentData.po_project_id) {
            return true;
        } else {
            return false;
        }
    }
}
